mapper.select:
SELECT 
FROM growth_code_review_record
WHERE id = #{id}
  AND user_id = #{userId}
LIMIT 1

mapper.update:
UPDATE growth_code_review_record
SET deleted = 1,
    update_time = NOW()
WHERE id = #{id}
  AND user_id = #{userId}
  AND deleted = 0

mapper.select:
SELECT 
FROM growth_code_review_record
WHERE user_id = #{userId}
  AND (
        #{afterUpdateTime} IS NULL
        OR update_time > #{afterUpdateTime}
        OR (update_time = #{afterUpdateTime} AND id > #{afterSourceId})
  )
ORDER BY update_time ASC, id ASC
LIMIT #{limit}

SELECT DISTINCT user_id
FROM growth_code_review_record
WHERE update_time >= #{updatedAfter}
ORDER BY user_id ASC
LIMIT #{limit}
